board = [list(map(int, input().split())) for _ in range(5)]
m = int(input())
calls = list(map(int, input().split()))

marked = [[False] * 5 for _ in range(5)]
answer = -1
for idx, x in enumerate(calls, 1):
    for r in range(5):
        for c in range(5):
            if board[r][c] == x:
                marked[r][c] = True
    lines = 0
    for i in range(5):
        if all(marked[i][j] for j in range(5)):
            lines += 1
        if all(marked[j][i] for j in range(5)):
            lines += 1
    if all(marked[i][i] for i in range(5)):
        lines += 1
    if all(marked[i][4 - i] for i in range(5)):
        lines += 1
    if lines >= 3:
        answer = idx
        break
print(answer)
